from datetime import date, timedelta
HOL = {
    date(2026,11,20): "Zumbi (Lei 14.759/2023)",
    date(2026,12,8):  "N. Sra. Conceicao - Campinas",
    date(2026,12,24): "sem expediente forense",
    date(2026,12,25): "Natal",
    date(2027,1,1):   "Confraternizacao",
}
def recess(d):  # CPC art. 220: 20/12 a 20/01, inclusive
    return date(2026,12,20) <= d <= date(2027,1,20)
def util(d):
    return d.weekday() < 5 and d not in HOL and not recess(d)
D = lambda s: date(*map(int, s.split("/")[::-1]))

# Correct convention (art. 231 VII + art. 224 caput + art. 224	ss3 + Lei 11.419 art. 4 ss3/ss4):
# comeco = data de publicacao (EXCLUIDO); first counted day = 1o dia util APONTADO como inicio_contagem (contado como dia 1).
def count(inicio, n):
    d, c = inicio, 0
    while True:
        if util(d):
            c += 1
            if c == n: return d
        d += timedelta(days=1)

def detail(inicio, n, tag):
    d, c = inicio, 0
    out = []
    while c < n:
        if util(d):
            c += 1; out.append(f"{c}:{d.strftime('%d/%m')}")
        d += timedelta(days=1)
    print(f"  {tag}: " + ", ".join(out))

print("== CONVENCAO CORRETA: comeco (publicacao) excluido; inicio_contagem contado como dia 1 ==")
print("[CITACAO] publicado 23/11(seg) = comeco EXCLUIDO")
detail(D("24/11/2026"), 15, "contestacao 15 dias")
print("[SENTENCA] publicado 11/12(sex) = comeco EXCLUIDO")
detail(D("14/12/2026"), 5,  "embargos 5 dias")
detail(D("14/12/2026"), 15, "apelacao 15 dias")
print("[DOBRO HIPOTETICO] (referencia apenas)")
detail(D("24/11/2026"), 30, "contestacao 30 dias")
